/* Persistent confirmations use server timestamps and the registered account country. */
window.MioActionConfirmation=(()=>{
 'use strict';
 let dialog=null,identity=null,restoreFocus=null;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const number=v=>new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:4}).format(Number(v));
 function country(code){const c=String(code||'').toUpperCase();if(!/^[A-Z]{2}$/.test(c))return {name:'Not set',flag:''};let name=c;try{name=new Intl.DisplayNames(['en'],{type:'region'}).of(c)||c}catch{}return {name,flag:c==='PK'?'<img src="/assets/flag-pk.svg" alt="" width="18" height="13">':`<span aria-hidden="true">${String.fromCodePoint(...[...c].map(x=>127397+x.charCodeAt(0)))}</span>`}}
 function clear(){const old=dialog;dialog=null;if(old){if(old.open&&old.close)old.close();old.remove()}document.body.classList.remove('action-confirmation-open');if(restoreFocus?.isConnected)restoreFocus.focus({preventScroll:true});restoreFocus=null;}
 function setIdentity(uid){if(uid!==identity){clear();identity=uid}}
 function show(model){
  if(!identity||model.owner!==identity)return;
  clear();restoreFocus=document.activeElement;
  const transfer=model.kind==='transfer',error=model.kind==='error',restricted=model.kind==='restriction',subscription=!transfer&&!error&&!restricted;
  const title=error||restricted?model.title:transfer?'Points Transferred Successfully!':`Congratulations${model.name?', '+model.name:''}!`;
  const timestamp=model.date?new Date(model.date):null,validDate=timestamp&&!Number.isNaN(timestamp.getTime()),region=country(model.country);
  const dateText=validDate?new Intl.DateTimeFormat('en-GB',{timeZone:'UTC',day:'2-digit',month:'short',year:'numeric'}).format(timestamp):'Unavailable';
  const timeText=validDate?new Intl.DateTimeFormat('en-GB',{timeZone:'UTC',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).format(timestamp)+' UTC':'Unavailable';
  const message=error||restricted?model.message:transfer?'Your MIO Points have been transferred successfully.':`Your ${model.plan} subscription is now active.`;
  const card=document.createElement('dialog');dialog=card;card.className='action-confirmation'+(error||restricted?' action-confirmation-error':'')+(subscription?' subscription-confirmation':'');card.setAttribute('aria-labelledby','actionConfirmationTitle');card.setAttribute('aria-describedby','actionConfirmationMessage');card.setAttribute('closedby','none');
  const person=(label,p)=>`<div class="action-person"><span>${label}</span><div><strong>${esc(p?.name||'Member')}</strong><small>${esc(p?.code||'')}</small></div></div>`;
  card.innerHTML=`<article class="action-confirmation-card"><button type="button" class="action-confirmation-close" aria-label="Close confirmation">×</button>${subscription?'<img class="confirmation-brand" src="/market-is-online-logo-header.svg" alt="Market is Online">':''}<div class="action-confirmation-mark" aria-hidden="true">${error?'!':restricted?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/></svg>':'✓'}</div>${subscription?'<div class="confirmation-kicker">Subscription confirmed</div>':''}<h2 id="actionConfirmationTitle">${esc(title)}</h2><p id="actionConfirmationMessage" class="action-confirmation-message">${esc(message)}</p>${subscription?'<p class="action-confirmation-welcome">Welcome to your next chapter with Market Is Online. Enjoy the benefits of your new subscription.</p>':''}${error?'':`<div class="action-confirmation-value"><span>${transfer?'POINTS TRANSFERRED':restricted?'CURRENT SUBSCRIPTION':'YOUR SUBSCRIPTION'}</span>${transfer?`<strong>${number(model.amount)} <small>MIO</small></strong>`:`<strong>${esc(model.plan)}</strong><b>${number(model.amount)} MIO Points</b>`}<em>✓ ${transfer?'Completed':'Active'}</em></div>`}${transfer?`<div class="action-confirmation-people">${person('FROM',model.sender)}<div class="action-person-arrow" aria-hidden="true">↓</div>${person('TO',model.receiver)}</div><div class="action-confirmation-verified">✓ Recipient verified</div>${model.download?'<button type="button" class="btn action-confirmation-download">↓ Download receipt</button>':''}`:''}${restricted&&model.upgrades?`<p class="confirmation-upgrades">Available upgrades: ${esc(model.upgrades)}</p>`:''}${restricted&&model.onUpgrade?'<button type="button" class="btn primary confirmation-upgrade">View higher packages</button>':''}${!error&&!restricted?`<div class="action-confirmation-datetime ${subscription?'with-country':''}"><div><span>Date</span><strong>${esc(dateText)}</strong></div><div><span>Time (UTC)</span><strong>${esc(timeText)}</strong></div>${subscription?`<div><span>Country</span><strong class="confirmation-country" title="${esc(region.name)}">${region.flag}<span>${esc(region.name)}</span></strong></div>`:''}</div>`:''}<p class="action-confirmation-status" role="status" aria-live="polite"></p><small class="action-confirmation-hint">Close this card whenever you’re ready.</small></article>`;
  document.body.append(card);document.body.classList.add('action-confirmation-open');
  card.querySelector('.action-confirmation-close').onclick=clear;
  card.addEventListener('cancel',e=>e.preventDefault());
  card.querySelector('.confirmation-upgrade')?.addEventListener('click',()=>{clear();model.onUpgrade()});
  card.querySelector('.action-confirmation-download')?.addEventListener('click',async e=>{const button=e.currentTarget;button.disabled=true;try{await model.download();if(dialog===card)card.querySelector('.action-confirmation-status').textContent='Receipt downloaded.'}catch{if(dialog===card)card.querySelector('.action-confirmation-status').textContent='Receipt download is unavailable. Please try again or open Transaction history.'}finally{button.disabled=false}});
  if(card.showModal)card.showModal();else card.setAttribute('open','');
  card.querySelector('.action-confirmation-close').focus();
 }
 function credentialError(error){const message=String(error?.message||error||'');if(/(?:invalid|incorrect|wrong).*(?:transaction\s+)?pin|pin.*(?:invalid|incorrect|wrong)/i.test(message))return {title:'Incorrect PIN',message:'Your transaction PIN is incorrect. Please enter the correct PIN and try again.'};if(/invalid login credentials|(?:invalid|incorrect|wrong).*password|password.*(?:invalid|incorrect|wrong)|password verification failed/i.test(message))return {title:'Incorrect password',message:'Your password is incorrect. Please enter the correct password and try again.'};return null;}
 function showCredentialError(error,owner){const message=credentialError(error);if(!message||!identity||owner!==identity)return false;show({kind:'error',owner,...message});return true;}
 return {show,clear,setIdentity,credentialError,showCredentialError};
})();
